$('import').onclick=()=>chooseFile('csv');$('restore').onclick=()=>chooseFile('vault');
async function googleToken(){if(token&&Date.now()<tokenExpiry)return token;if(!window.google?.accounts?.oauth2)await new Promise((res,rej)=>{const s=element('script');s.src='https://accounts.google.com/gsi/client';s.onload=res;s.onerror=()=>rej(Error('Không tải được đăng nhập Google. Kiểm tra kết nối.'));document.head.append(s)});oauthPending=true;return new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:DEFAULT_CLIENT,scope:'https://www.googleapis.com/auth/drive.appdata',callback:r=>{oauthPending=false;if(r.error)return reject(Error('Google từ chối đăng nhập: '+r.error));token=r.access_token;tokenExpiry=Date.now()+(Number(r.expires_in)-60)*1000;resolve(token)},error_callback:()=>{oauthPending=false;reject(Error('Đăng nhập chưa hoàn tất. Kiểm tra popup và Authorized JavaScript origins.'))}});client.requestAccessToken({prompt:'select_account'})})}
async function driveFetch(path,options={}){const t=await googleToken();const r=await fetch('https://www.googleapis.com/'+path,{...options,headers:{Authorization:'Bearer '+t,...options.headers}});if(!r.ok){if(r.status===401){token=null;tokenExpiry=0}throw Error(`Google Drive báo lỗi ${r.status}. Kiểm tra quyền Drive API và đăng nhập lại.`)}return r}
async function upload(){if(!key)throw Error('Mở khóa kho trước khi lưu Drive.');await uploadEnvelope(localStorage.getItem(STORE),await googleToken());$('drive-status').textContent='Đã lưu bản mã lên Drive';toast('Đã lưu bản sao mã hóa mới trên Drive.')}
async function uploadEnvelope(envelope,accessToken){const boundary='safeincloud_'+crypto.randomUUID(),name='AT_SafeInCloud.vault';const body=`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify({name,parents:['appDataFolder'],appProperties:{app:'safeincloud-v1'}})}\r\n--${boundary}\r\nContent-Type: application/json\r\n\r\n${envelope}\r\n--${boundary}--`;const response=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart',{method:'POST',headers:{Authorization:'Bearer '+accessToken,'Content-Type':'multipart/related; boundary='+boundary},body});if(!response.ok)throw Error('Không lưu được kho trên Google Drive. Kho cũ được giữ nguyên. Hãy chọn lại tài khoản và thử lại.')}
async function pull(){const q="trashed = false and appProperties has { key='app' and value='safeincloud-v1' }";const r=await driveFetch('drive/v3/files?spaces=appDataFolder&pageSize=1&orderBy=createdTime%20desc&fields=files(id,name)&q='+encodeURIComponent(q));const data=await r.json();if(!data.files.length)throw Error('Tài khoản Google này chưa có kho SafeinCloud.');const f=await driveFetch('drive/v3/files/'+encodeURIComponent(data.files[0].id)+'?alt=media');await restoreEnvelope(await f.json())}
$('sync').onclick=()=>run(async()=>{$('settings').close();if(await confirmAction('Lưu lên Google Drive','Tạo bản sao mã hóa mới trên tài khoản Google bạn chọn. Để lấy dữ liệu từ thiết bị khác, chọn “Mở kho từ Google Drive” trong Cài đặt.'))await upload()});$('gate-drive').onclick=()=>run(async()=>{$('settings').close();await pull()});
document.querySelectorAll('[data-password]').forEach(b=>b.onclick=()=>{const input=$(b.dataset.password),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Ẩn':'Hiện';b.setAttribute('aria-pressed',String(show))});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());['pointerdown','keydown','input'].forEach(e=>document.addEventListener(e,()=>lastActivity=Date.now(),{passive:true}));setInterval(()=>{if(key&&Date.now()-lastActivity>300000)lock()},1000);document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();if(key&&!oauthPending&&!authPending)lock();else if(key){$('detail').replaceChildren();$('fields').replaceChildren();if($('editor').open)$('editor').close()}}else if(hiddenAt&&Date.now()-hiddenAt>300000)lock();else if(key)render()});window.addEventListener('storage',e=>{if(e.key===STORE){lock();expected=e.newValue;toast('Kho đã thay đổi ở cửa sổ khác. Hãy mở khóa lại.')}});window.addEventListener('pagehide',lock);gate();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});


function clearDb(){dbAttempt++;pendingDb?.fill(0);pendingDb=null;dbBusy=false;$('db-password').value='';$('db-password').type='password';$('db-status').textContent='';$('db-decrypt').disabled=false;}
$('import-db').onclick=()=>chooseFile('db');
$('db-import').addEventListener('close',clearDb);
$('db-import-form').onsubmit=e=>{e.preventDefault();if(dbBusy||!pendingDb||!key)return;run(async()=>{
 const ticket=epoch,attempt=dbAttempt,data=pendingDb.slice();let password=$('db-password').value;
 if(!password){$('db-status').textContent='Hãy nhập mật khẩu của file .db.';data.fill(0);return}
 $('db-password').value='';dbBusy=true;$('db-decrypt').disabled=true;$('db-status').textContent='Đang giải mã trên thiết bị…';let result;
 try{
  result=await importDatabase(data,password);password='';
  if(ticket!==epoch||attempt!==dbAttempt||!key)return;
  if(items.length+result.items.length>20000)throw Error('Kho vượt quá 20.000 mục.');
  $('db-import').close();clearDb();
  if(!result.items.length){toast('File không có mục đang sử dụng để nhập.');return}
  const fileSummary=result.attachments?` Phục hồi được ${result.attachments} tệp đính kèm${result.skippedAttachments?`; bỏ qua ${result.skippedAttachments} tệp lỗi hoặc quá lớn`:''}.`:result.skippedAttachments?` Bỏ qua ${result.skippedAttachments} tệp đính kèm lỗi hoặc quá lớn.`:'';
  const historySummary=result.skippedHistory?` Bỏ qua ${result.skippedHistory} trường hoặc giá trị Lịch sử.`:'';
  const accepted=await confirmAction('Nhập dữ liệu SafeInCloud',`Đã giải mã ${result.items.length} mục.${fileSummary}${historySummary} Bỏ qua ${result.templates} mẫu và ${result.deleted} mục đã xóa. Thêm vào kho hiện tại? Mục trùng vẫn được nhập. Dữ liệu và tệp đính kèm sẽ được mã hóa bằng mật khẩu kho hiện tại.`);
  if(!accepted||ticket!==epoch||!key)return;
  let restored=result.attachments,skipped=result.skippedAttachments;
  try{await persist([...items,...result.items])}catch(error){
   if(!restored||!(/quota|storage|dung lượng/i.test(`${error.name} ${error.message}`)))throw error;
   const withoutFiles=result.items.map(item=>{const copy={...item};delete copy.attachments;return copy});
   await persist([...items,...withoutFiles]);skipped+=restored;restored=0;
  }
  render();toast(`Đã nhập ${result.items.length} mục${restored?` và ${restored} tệp đính kèm`:''} từ .db.${skipped?` Đã bỏ qua ${skipped} tệp không thể lưu.`:''} Hãy sao lưu AT_SafeInCloud.vault.`);
 }catch(error){if(ticket===epoch&&attempt===dbAttempt&&key)$('db-status').textContent=error.message;else if(ticket===epoch&&key)throw error;}
 finally{password='';data.fill(0);if(result)result.items.length=0;if(attempt===dbAttempt){dbBusy=false;$('db-decrypt').disabled=false;}}
 });};
